<script setup lang="ts">
import {computed} from 'vue'
import type {PracticeQuestionInput} from '@/api/practice'
import {questionTypes,questionProblems} from '@/practice/admin-draft'
const props=defineProps<{questions:PracticeQuestionInput[];index:number;reviewed:string[];busy:boolean;onlyProblems:boolean;listening?:boolean}>()
const emit=defineEmits<{change:[key:string];navigate:[index:number];reorder:[direction:number];add:[];remove:[];review:[key:string,checked:boolean];'update:onlyProblems':[boolean]}>()
const q=computed(()=>props.questions[props.index]!)
</script>
<template><section class="practice-panel practice-question-editor"><h2>题目与解析</h2><div class="practice-edit-body"><div class="practice-current-question"><div class="practice-actions"><h3>第 {{index+1}} 题 / {{questions.length}}</h3><button type="button" :disabled="busy||index===0" @click="emit('reorder',-1)">上移</button><button type="button" :disabled="busy||index===questions.length-1" @click="emit('reorder',1)">下移</button><button type="button" :disabled="busy||questions.length===1" @click="emit('remove')">移除</button></div><fieldset :disabled="busy" @input="emit('change',q.key)" @change="emit('change',q.key)"><label>题目分类<select v-if="!listening" v-model="q.type"><option v-for="(label,code) in questionTypes" :key="code" :value="code">{{label}}</option></select></label><label>英文题干<textarea id="practice-stem" v-model="q.stem" rows="3" maxlength="2000"/></label><label v-for="(_,o) in q.options" :key="o">选项{{'ABCD'[o]}}<input :id="o===0?'practice-options':undefined" v-model="q.options[o]" maxlength="1000"></label><label>正确答案<select id="practice-correctOption" v-model="q.correctOption"><option :value="null">请选择答案</option><option v-for="letter in 'ABCD'" :key="letter" :value="letter">{{letter}}</option></select></label><label>答案解析<textarea id="practice-explanation" v-model="q.explanation" rows="4" maxlength="4000"/></label></fieldset><label class="practice-checkbox"><input :checked="reviewed.includes(q.key)" type="checkbox" :disabled="busy" @change="emit('review',q.key,($event.target as HTMLInputElement).checked)">已校对本题题干、四个选项、答案与解析</label><div class="practice-question-steps"><button :disabled="busy||index===0" @click="emit('navigate',index-1)">上一题</button><button :disabled="busy||index===questions.length-1" @click="emit('navigate',index+1)">下一题</button></div></div><aside class="practice-question-nav"><h3>组内题目导航</h3><label class="practice-checkbox"><input type="checkbox" :checked="onlyProblems" @change="emit('update:onlyProblems',($event.target as HTMLInputElement).checked)">仅查看有问题的题</label><div class="practice-question-numbers"><template v-for="(item,n) in questions" :key="item.key"><button v-if="!onlyProblems||questionProblems(item,reviewed.includes(item.key)).length" :aria-pressed="n===index" :disabled="busy" @click="emit('navigate',n)">{{n+1}}<small>{{questionProblems(item,reviewed.includes(item.key)).join(' / ')||'已校对'}}</small></button></template></div><p v-if="onlyProblems&&questions.every(item=>!questionProblems(item,reviewed.includes(item.key)).length)" class="practice-hint">全部题目已完成校对。</p><button :disabled="busy||questions.length>=(listening?50:10)" @click="emit('add')">＋ 添加</button><p class="practice-hint">每组最多{{listening?50:10}}题，切题保留当前编辑。</p></aside></div></section></template>
